      {"matcher": "Bash", "hooks": [{"type": "command", "command": "rtk hook claude"}]},
      {"matcher": "Edit|Write", "hooks": [{"type": "command", "command": `+strconv.Quote(legacyWindowsPreEditHookCommand)+`, "timeout": 5}]}
    ]
  }
}`)

