		t.Fatalf("upgrade: changed=%v err=%v", changed, err)
	}
	if got := preEditHookCommandsIn(t, settingsPath); !slices.Equal(got, []string{windowsPreEditHookCommand}) {
		t.Fatalf("want exactly the current windows form, got %q", got)
